(()=>{
const main=document.querySelector('main'),D=window.ARCHIVE,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const route=location.pathname.split('/').filter(Boolean),url=p=>p.includes('?')?'/'+p.replace('?','/?'):'/'+(p?p+'/':''),link=(p,t,cls='')=>`<a class="${cls}" href="${url(p)}">${t}</a>`;
const bookUrl=p=>`obra/${p.id}`,sourceLink=(u,t='Consultar la fuente original')=>`<a href="${esc(u)}" target="_blank" rel="noopener">${t} ↗</a>`;
const bread=(label,parent='')=>`<div class="breadcrumb">${link('','Inicio')}${parent?` / ${link(parent,parent==='obra'?'Obra':'Conversaciones')}`:''} / <span>${esc(label)}</span></div>`;
const heading=(title,sub='')=>`<div class="page-heading"><h1>${title}</h1>${sub?`<p class="lead">${sub}</p>`:''}</div>`;
const cover=p=>p.cover?`<img src="/assets/${p.cover}" alt="Portada de ${esc(p.title)}" loading="lazy">`:`<div class="catalog-cover tone-${p.year%3}"><span>${esc(p.type)}</span><strong>${esc(p.title)}</strong><span>Germán Rodrigo<br>Mejía Pavony</span><small>Ficha bibliográfica · ${p.year}</small></div>`;
const row=p=>`<article class="publication-row"><div class="record-year">${p.year}<small>${esc(p.type)}</small></div><div><h2>${link(bookUrl(p),esc(p.title))}</h2><p>${esc(p.publisher)}</p><span class="record-meta">${esc(p.role)} · ${esc(p.topic)}</span></div>${link(bookUrl(p),'Ver ficha','record-action')}</article>`;
function title(t){document.title=t+' · Germán Rodrigo Mejía Pavony'}
function page(content){main.innerHTML=`<div class="inner-page wrap">${content}</div>`;document.body.classList.add('internal-page')}
const related=p=>D.publications.filter(x=>x.id!==p.id&&x.topic===p.topic).slice(0,3).map(row).join('');
function detail(p){title(p.title);page(`${bread(p.type,'obra')}<div class="publication-detail"><aside class="cover-column">${cover(p)}${!p.cover?'<small>Representación tipográfica del registro.<br>No corresponde a una portada editorial.</small>':''}</aside><article><p class="record-meta">${esc(p.type)} · ${p.year}</p><h1>${esc(p.title)}</h1><p class="lead">Germán Rodrigo Mejía Pavony</p><dl class="metadata"><div><dt>Participación</dt><dd>${esc(p.role)}</dd></div><div><dt>Publicación</dt><dd>${esc(p.publisher)}</dd></div><div><dt>Año</dt><dd>${p.year}</dd></div><div><dt>Tema</dt><dd>${link('obra?tema='+encodeURIComponent(p.topic),esc(p.topic))}</dd></div>${p.isbn?`<div><dt>ISBN</dt><dd>${p.isbn}</dd></div>`:''}</dl>${p.description?`<section class="reading"><h2>Sobre esta publicación</h2><p>${esc(p.description)}</p></section>`:''}${p.editions?`<section class="reading"><h2>Ediciones</h2><p>${esc(p.editions)}</p></section>`:''}<section class="reading citation"><h2>Referencia bibliográfica</h2><p id="citation">Mejía Pavony, Germán Rodrigo (${p.year}). ${esc(p.title)}. ${esc(p.publisher)}.${p.role!=='Autor'?' Participación: '+esc(p.role)+'.':''}</p><button class="text-link" id="copy-citation">Copiar referencia</button><span id="copy-status" role="status"></span></section><section class="reading"><h2>Consulta y procedencia</h2><p>${p.source.includes('academia.edu')?'Referencia registrada en la hoja de vida histórica del autor.':'Referencia contrastada con la fuente editorial o institucional enlazada.'} Esta ficha no incluye el texto completo de la publicación.</p>${sourceLink(p.source,p.source.includes('academia.edu')?'Ver la hoja de vida utilizada como fuente':'Consultar publicación en su fuente')}</section></article></div><section class="related"><h2>Continuar leyendo</h2>${related(p)}${link('obra','Volver al catálogo completo','text-link')}</section>`);document.querySelector('#copy-citation').onclick=async()=>{const t=document.querySelector('#citation').textContent;try{await navigator.clipboard.writeText(t);document.querySelector('#copy-status').textContent='Referencia copiada.'}catch{document.querySelector('#copy-status').textContent='Seleccione la referencia para copiarla.'}}}
function catalog(episodes=false){
const params=new URLSearchParams(location.search),items=episodes?D.episodes:D.publications;
title(episodes?'En los tiempos del ruido':'Obra y publicaciones');
page(`${bread(episodes?'Conversaciones':'Obra')}${heading(episodes?'En los tiempos del ruido':'Pensar la historia<br>desde nuevas preguntas',episodes?'Explore los capítulos de Germán Mejía Pavony. La reproducción se realiza en Javeriana Estéreo.':'Libros, artículos, capítulos y otros escritos.')}${episodes?'<img class="archive-banner" src="/assets/radio.jpg" alt="Germán Mejía Pavony, a la izquierda, en el estudio de Javeriana Estéreo">':''}<form class="catalog-controls" id="filters" role="search"><label class="search-label">${episodes?'Buscar un episodio':'Buscar en la obra'}<input name="q" type="search" placeholder="${episodes?'Imprenta, teatro, Santafé…':'Título, publicación o palabra clave…'}" value="${esc(params.get('q')||'')}"></label>${!episodes?`<label>Tipo de publicación<select name="tipo"><option value="">Todas las publicaciones</option>${[...new Set(items.map(p=>p.type))].map(t=>`<option ${params.get('tipo')===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Tema<select name="tema"><option value="">Todos los temas</option>${[...new Set(items.map(p=>p.topic))].sort().map(t=>`<option ${params.get('tema')===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Orden<select name="orden"><option value="reciente">Más recientes</option><option value="antiguo" ${params.get('orden')==='antiguo'?'selected':''}>Más antiguos</option><option value="titulo" ${params.get('orden')==='titulo'?'selected':''}>Título A–Z</option></select></label>`:''}<button class="button" type="submit">Buscar</button></form><div class="catalog-summary"><p id="results-status" role="status"></p><a href="${episodes?'/conversaciones/':'/obra/'}">Limpiar filtros</a></div><div id="results"></div><nav class="pagination" aria-label="Páginas del catálogo"></nav><p class="catalog-footnote">${episodes?'Títulos y videos organizados a partir del archivo de Javeriana Estéreo. La numeración reproduce la fuente, que contiene algunas inconsistencias.':'Catálogo bibliográfico reunido a partir de la hoja de vida del autor y de fuentes editoriales. Las reediciones se agrupan cuando están identificadas; el inventario puede ampliarse con nuevos registros.'}</p>${!episodes?'<a class="text-link" href="/catalog.json" download="bibliografia-german-mejia.json">Descargar los registros del catálogo</a>':''}`);
let result=items.filter(p=>norm([p.title,p.publisher,p.topic,p.year].join(' ')).includes(norm(params.get('q')||''))&&(episodes||(!params.get('tipo')||params.get('tipo')===p.type)&&(!params.get('tema')||params.get('tema')===p.topic)));
if(!episodes)result.sort((a,b)=>params.get('orden')==='titulo'?a.title.localeCompare(b.title,'es'):params.get('orden')==='antiguo'?a.year-b.year:b.year-a.year);
const pages=Math.max(1,Math.ceil(result.length/9)),current=Math.max(1,Math.min(pages,Number(params.get('pagina'))||1)),visible=result.slice((current-1)*9,current*9);
document.querySelector('#results-status').textContent=`${result.length} ${episodes?'episodios':'publicaciones'} · Página ${current} de ${pages}`;
document.querySelector('#results').innerHTML=visible.length?(episodes?`<div class="episode-list">${visible.map(p=>`<article><span class="episode-mark" aria-hidden="true">▶</span><div><h2>${sourceLink(p.source,esc(p.title))}</h2><p>En los tiempos del ruido · Javeriana Estéreo</p></div>${sourceLink(p.source,'Escuchar en Javeriana Estéreo')}</article>`).join('')}</div>`:visible.map(row).join('')):`<div class="empty-state"><h2>No encontramos coincidencias</h2><p>Pruebe con otra palabra o quite alguno de los filtros.</p></div>`;
document.querySelector('.pagination').innerHTML=Array.from({length:pages},(_,i)=>{const q=new URLSearchParams(params);q.set('pagina',i+1);return `<a href="?${q}" ${current===i+1?'aria-current="page"':''} aria-label="Página ${i+1}">${i+1}</a>`}).join('');
document.querySelector('#filters').onsubmit=e=>{e.preventDefault();const q=new URLSearchParams();for(const [k,v] of new FormData(e.target))if(v)q.set(k,v);location.search=q.toString()};
}
const press=[{id:'san-victorino',title:'San Victorino: pasado y presente de la capital',medium:'Radio Nacional de Colombia',kind:'En la prensa',image:'plaza-bolivar-bogota.jpg',text:'San Victorino ofrece una entrada a las transformaciones del centro de Bogotá. Esta pieza de Radio Nacional reúne una mirada al pasado y al presente de ese sector de la capital.',source:'https://www.radionacional.co/cultura/san-victorino-pasado-y-presente-de-la-capital'}, {id:'entrevista-uniciso',title:'Un poco de historia y consejos para proyectos',medium:'Portal Uniciso',kind:'Entrevista',image:'radio.jpg',text:'Una conversación con Germán Mejía Pavony presentada por Portal Uniciso. El encuentro acerca el oficio del historiador a quienes están formulando sus propios proyectos de investigación.',source:'https://www.portaluniciso.com/producto/podcast-un-poco-de-historia-y-tps-para-tus-proyectos-invitado-german-mejia-pavony/'},{id:'perfil-javeriana',title:'Germán Mejía Pavony en la Universidad Javeriana',medium:'Pontificia Universidad Javeriana',kind:'Perfil',image:'german.png',text:'La Universidad Javeriana es un eje de la vida académica de Germán Mejía Pavony: allí se formó, ejerció la docencia y fue decano de la Facultad de Ciencias Sociales. Su perfil institucional complementa la trayectoria reunida en esta web.',source:'https://cienciassociales.javeriana.edu.co/w/germ%C3%A1n-mej%C3%ADa-pavony'}];
if(!route.length)return;
if(route[0]==='obra'){const p=D.publications.find(p=>p.id===route[1]);if(route[1]&&p)detail(p);else if(!route[1])catalog();else page(heading('Publicación no encontrada')+link('obra','Volver al catálogo','button'))}
else if(route[0]==='conversaciones'){
const e=D.episodes.find(e=>e.id===route[1]);if(e){title(e.title);page(`${bread('Episodio','conversaciones')}${heading(esc(e.title))}<p class="lead">Germán Mejía Pavony · Javeriana Estéreo</p><div class="reading"><h2>La historia, en conversación</h2><p>Un episodio del archivo de <em>En los tiempos del ruido</em>. Para escuchar este capítulo, visite el archivo del programa en Javeriana Estéreo y seleccione su título.</p>${sourceLink(e.source,'Escuchar en Javeriana Estéreo')}</div><div class="actions">${link('conversaciones','Todos los episodios','button')}${link('obra','Explorar sus publicaciones','text-link')}</div>`)}else catalog(true)
}else if(route[0]==='trayectoria'){
title('Trayectoria');page(`${bread('Trayectoria')}<div class="bio-intro"><div>${heading('Una vida dedicada<br>a la historia')}<p class="lead">Investigación, docencia y conversación pública.</p><p>Nacido en Pereira en 1954, Germán Rodrigo Mejía Pavony ha dedicado su trabajo a comprender las ciudades y las sociedades que las construyen. Bogotá ocupa un lugar central en una obra que también recorre Colombia y América Latina.</p></div><img src="/assets/german.png" alt="Germán Rodrigo Mejía Pavony"></div><div class="biography-layout"><aside><a href="#formacion">Formación</a><a href="#docencia">Docencia e instituciones</a><a href="#investigacion">Investigación</a><a href="#reconocimientos">Reconocimientos</a></aside><article class="reading"><section id="formacion"><h2>Formación</h2><p>Es licenciado en Filosofía y Letras, con especialización en Historia, de la Pontificia Universidad Javeriana. Obtuvo el doctorado en Historia de América Latina en la Universidad de Miami en 1996.</p></section><section id="docencia"><h2>Enseñar, investigar, construir instituciones</h2><p>Su trayectoria está estrechamente ligada al Departamento de Historia de la Universidad Javeriana, donde fue profesor titular y director. También fue decano de su Facultad de Ciencias Sociales.</p><p>La docencia lo ha llevado a instituciones como las universidades Nacional de Colombia, de los Andes, Externado, Pedagógica Nacional, de Miami y Pedagógica y Tecnológica de Colombia, según los períodos recogidos en su hoja de vida.</p><dl class="timeline"><div><dt>1987–1991</dt><dd>Dirección del Departamento de Historia de la Universidad Javeriana.</dd></div><div><dt>2004–2007</dt><dd>Dirección del Archivo de Bogotá.</dd></div><div><dt>2008–2010</dt><dd>Asesoría al Ministerio de Cultura para el Bicentenario de la Independencia.</dd></div><div><dt>2012–2014</dt><dd>Dirección del Archivo Histórico Javeriano.</dd></div><div><dt>2012–2015</dt><dd>Decanatura académica de la Facultad de Ciencias Sociales. La hoja de vida registra el inicio de una nueva etapa como decano en 2016.</dd></div></dl></section><section id="investigacion"><h2>La ciudad como pregunta</h2><p>Sus publicaciones permiten seguir una investigación sostenida sobre la historia urbana: desde la Santafé de los conquistadores hasta las transformaciones de Bogotá en el siglo XIX y la experiencia urbana latinoamericana.</p><p>A ese campo se suman la historiografía, la historia de Colombia y la reflexión sobre las maneras de escribir e interpretar el pasado. El catálogo distingue los libros de autoría individual, las obras colectivas y los textos publicados en revistas y volúmenes académicos.</p>${link('obra','Recorrer la obra','text-link')}</section><section id="reconocimientos"><h2>Reconocimiento académico</h2><p>Es investigador emérito del Sistema Nacional de Ciencia, Tecnología e Innovación y profesor honorario de la Universidad Nacional de Colombia. Es miembro fundador de la Academia de Historia de Bogotá, miembro correspondiente de la Academia Colombiana de Historia y miembro de la Red Colombiana de Historia Urbana.</p></section><section><h2>Una conversación que continúa</h2><p>Su actividad pública se prolonga en conferencias, encuentros y conversaciones de radio. Esta web reúne esas distintas formas de acercarse a la historia y permite a instituciones y lectores explorar su trabajo.</p><div class="actions">${link('conferencias','Conferencias y encuentros','button')}${link('conversaciones','Escuchar el podcast','text-link')}</div></section><section class="source-notes"><h2>Fuentes de la trayectoria</h2><p>Las fechas históricas proceden de la hoja de vida disponible; no se presentan sus cargos abiertos como cargos actuales.</p>${sourceLink('https://javeriana.academia.edu/Germ%C3%A1nMej%C3%ADa/CurriculumVitae','Hoja de vida') } · ${sourceLink('https://www.penguinlibros.com/es/994620-german-r-mejia-pavony','Perfil editorial')}</section></article></div>`)
}else if(route[0]==='conferencias'){
title('Conferencias y encuentros');const themes=[['church','Bogotá','Ciudad, memoria y transformación','La fundación de Santafé, la vida urbana colonial y los cambios de Bogotá durante los siglos XIX y XX. Un campo para conversar sobre patrimonio, territorio y memoria.','Bogotá'],['mountains','Colombia','Procesos, sociedades y territorios','La formación del país, las independencias y las tradiciones políticas. Preguntas que conectan la investigación histórica con la comprensión del presente.','Colombia'],['map','América Latina','Historias conectadas','La experiencia de las ciudades latinoamericanas y el desarrollo de la historia urbana como campo de investigación.','América Latina']];page(`${bread('Conferencias')}${heading('Diálogos para comprender<br>nuestro tiempo')}<div class="talk-list">${themes.map(t=>`<section><div class="illustration ${t[0]}" aria-hidden="true"></div><div><h2>${t[1]}</h2><h3>${t[2]}</h3><p>${t[3]}</p><a class="text-link" href="/obra/?tema=${encodeURIComponent(t[4])}">Publicaciones relacionadas</a></div></section>`).join('')}</div><section class="format-section"><h2>Un encuentro a la medida de su institución</h2><div class="format-grid"><article><h3>Conferencias</h3><p>Encuentros dirigidos a comunidades académicas, instituciones culturales y públicos interesados en la historia.</p></article><article><h3>Talleres y seminarios</h3><p>Espacios para trabajar preguntas, fuentes y perspectivas de investigación con estudiantes y profesionales.</p></article><article><h3>Clases y conversaciones</h3><p>Participaciones en programas de formación, diálogos públicos y entrevistas.</p></article></div><p>Estos ejes se proponen a partir de su obra. El tema específico, la duración, la modalidad y la disponibilidad deben acordarse con Germán.</p>${link('contacto','Preparar una invitación','button')}</section>`)
}else if(route[0]==='prensa'){
const p=press.find(p=>p.id===route[1]);title(p?p.title:'Germán y la prensa');page(p?`${bread('Prensa')}${heading(p.title)}<p class="record-meta">${p.kind} · ${p.medium}</p><img class="press-detail-image" src="/assets/${p.image}" alt="${p.id==='perfil-javeriana'?'Germán Mejía Pavony':'Imagen contextual del archivo del sitio'}"><article class="reading"><h2>Sobre esta pieza</h2><p>${p.text}</p><p>Presentación editorial de la referencia. El contenido íntegro pertenece a su medio original.</p>${sourceLink(p.source,'Leer o escuchar en '+p.medium)}</article>${link('prensa','Volver a Germán y la prensa','text-link')}`:`${bread('Prensa')}${heading('Homenajes y perfiles')}<div class="press-index">${press.map(p=>`<article><img src="/assets/${p.image}" alt="${p.id==='perfil-javeriana'?'Germán Mejía Pavony':'Imagen contextual'}"><div><p class="record-meta">${p.kind} · ${p.medium}</p><h2>${link('prensa/'+p.id,p.title)}</h2><p>${p.text}</p>${link('prensa/'+p.id,'Ver la pieza','text-link')}</div></article>`).join('')}</div><section class="reading"><h2>Homenajes</h2><p>Esta categoría se ampliará con homenajes documentados. Las referencias disponibles se presentan como perfiles, entrevistas y participaciones en prensa.</p></section>`)
}else if(route[0]==='contacto'){
title('Invitar a Germán');page(`${bread('Contacto')}${heading('Preparemos una conversación')}<div class="contact-page"><div><h2>Invítelo a su institución</h2><p>Indique el tema, el público y las fechas del encuentro para preparar una propuesta de conferencia, taller, clase o entrevista.</p><p class="notice">El canal directo está pendiente de confirmación. Este formulario permite descargar un borrador; todavía no envía mensajes ni confirma disponibilidad.</p>${link('conferencias','Explorar los temas','text-link')}</div><form id="invite-form"><label>Nombre<input name="nombre" required autocomplete="name"></label><label>Institución<input name="institucion" required autocomplete="organization"></label><label>Correo electrónico<input name="correo" type="email" required autocomplete="email"></label><label>Formato<select name="formato"><option>Conferencia</option><option>Taller</option><option>Clase o seminario</option><option>Entrevista</option></select></label><label>Fecha y lugar previstos<input name="lugar" placeholder="Ciudad, modalidad y fecha aproximada"></label><label>Sobre el encuentro<textarea name="mensaje" required placeholder="Tema, público y objetivos"></textarea></label><button class="button" type="submit">Descargar borrador de invitación</button><p class="status" aria-live="polite"></p></form></div>`)
}
document.querySelectorAll('header nav a').forEach(a=>{if(new URL(a.href).pathname.split('/')[1]===route[0])a.setAttribute('aria-current','page')});
})();
